import React from "react";

const products = [
  {
    id: 1,
    name: "Pure Forest Honey",
    price: "₹450",
    image:
      "https://images.unsplash.com/photo-1587049352851-8d4e89133924",
  },
  {
    id: 2,
    name: "Wildflower Honey",
    price: "₹380",
    image:
      "https://images.unsplash.com/photo-1615486363138-7dfbde6a5d63",
  },
  {
    id: 3,
    name: "Organic Raw Honey",
    price: "₹520",
    image:
      "https://images.unsplash.com/photo-1604908176997-4310f1d2e4f5",
  },
];

function Home() {
  return (
    <div>
      {/* Navbar */}
      <nav className="navbar navbar-expand-lg navbar-dark bg-warning px-4">
        <a className="navbar-brand fw-bold" href="#">Golden Honey</a>
        <div className="ms-auto">
          <a className="nav-link d-inline text-dark" href="#products">Products</a>
          <a className="nav-link d-inline text-dark" href="#contact">Contact</a>
        </div>
      </nav>

      {/* Hero Section */}
      <section className="text-center py-5 bg-light">
        <h1 className="fw-bold">100% Natural & Pure Honey 🍯</h1>
        <p className="lead">Fresh from the farm. No additives. No chemicals.</p>
        <button className="btn btn-warning btn-lg">Shop Now</button>
      </section>

      {/* Products */}
      <section id="products" className="container py-5">
        <h2 className="text-center mb-4 fw-bold">Our Products</h2>
        <div className="row">
          {products.map((product) => (
            <div key={product.id} className="col-md-4 mb-4">
              <div className="card shadow">
                <img
                  src={product.image}
                  className="card-img-top"
                  alt={product.name}
                  style={{ height: "250px", objectFit: "cover" }}
                />
                <div className="card-body text-center">
                  <h5 className="card-title">{product.name}</h5>
                  <p className="text-warning fw-bold">{product.price}</p>
                  <button className="btn btn-warning">
                    Buy Now
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* Contact */}
      <section id="contact" className="bg-light text-center py-5">
        <h2 className="fw-bold">Contact Us</h2>
        <p>📞 +91 98765 43210</p>
        <p>📍 Chennai, Tamil Nadu</p>
      </section>

      {/* Footer */}
      <footer className="bg-warning text-center py-3">
        <strong>© 2026 Golden Honey</strong>
      </footer>
    </div>
  );
}

export default Home;
